{
    /// <summary>The C names of these imports, sorted: what a library standing for the native ones must export.</summary>
    internal static IEnumerable<string> Imports => typeof(LlvmNative).GetMethods(System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Static)
        .Select(method => System.Reflection.CustomAttributeExtensions.GetCustomAttribute<DllImportAttribute>(method)?.EntryPoint).OfType<string>().Order(StringComparer.Ordinal);

